const slash = (p) => p.split(path.sep).join("/");
const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]));
const app = path.join(ROOT, "src/app");
const routen = walk(app)
  .filter((f) => /(page|route)\.js$/.test(path.basename(f)))
  .map((f) => "/" + slash(path.relative(app, path.dirname(f))))
  .map((r) => (r === "/" || r === "/." ? "/" : r))
  .map((r) => r.replace(/\/\([^)]*\)/g, "") || "/");
const pub = new Set(walk(path.join(ROOT, "public")).map((f) => "/" + slash(path.relative(path.join(ROOT, "public"), f))));
const passt = (url) => {
  const p = url.split(/[?#]/)[0].replace(/\/$/, "") || "/";
  if (p === "/") return true;
  if (pub.has(p)) return true;
  if (["/sitemap.xml", "/robots.txt", "/manifest.webmanifest", "/favicon.ico", "/icon.svg", "/opengraph-image"].includes(p)) return true;
  const seg = p.split("/");
  return routen.some((r) => {
    const rs = r.split("/");
    if (rs.length !== seg.length) return false;
    return rs.every((s, i) => s === seg[i] || s.startsWith("["));
  });
};
const bereiche = ["src/app", "src/components", "src/lib/rechner", "src/content", "src/data", "src/lib/ratgeber.js", "src/lib/invest"];
