  .filter((f) => /\.(js|mdx?|json)$/.test(f))
  .filter((f) => !/(^|\/)(portal|api|Portal|Plattform)\//.test(slash(path.relative(ROOT, f)).replace(/^src\/(app|components)\//, "")));
const re = /(?:href\s*[:=]\s*\{?\s*[`"']|\]\(|(?:link|pfad|ziel|url|zu)\s*:\s*["'`])(\/[a-zA-Z0-9\-_/.#?=&%]*)/g;
const tot = {};
for (const f of dateien) {
  const t = fs.readFileSync(f, "utf8");
  for (const m of t.matchAll(re)) {
    const u = m[1];
    if (u.startsWith("//") || u.startsWith("/api/") || u.startsWith("/img/") || u.startsWith("/portal")) continue;
    if (!passt(u)) (tot[u] ||= new Set()).add(slash(path.relative(ROOT, f)) + ":" + t.slice(0, m.index).split("\n").length);
  }
}
for (const [u, s] of Object.entries(tot)) console.log(u, "<-", [...s].slice(0, 5).join(", "));
console.log("Dateien:", dateien.length, "Routen:", routen.length, "tote:", Object.keys(tot).length);

