// Sequentieller Crawl aller Sitemap-URLs gegen den Dev-Server (Team 5)
import fs from "node:fs";
const BASIS = "http://localhost:3100";
const argUrls = process.argv.slice(2);
const urls = argUrls.length
  ? argUrls
  : fs.readFileSync(new URL("./urls.txt", import.meta.url), "utf8").split(/\r?\n/).filter(Boolean).map((u) => u.replace(/^https?:\/\/[^/]+/, "") || "/");
fs.mkdirSync(new URL("./html/", import.meta.url), { recursive: true });
const titel = {};
const ergebnis = [];
const dec = (s) => s.replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#x27;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">");
for (const pfad of urls) {
  const t0 = Date.now();
  let status, html = "";
  try {
    const r = await fetch(BASIS + pfad, { signal: AbortSignal.timeout(180000), redirect: "manual" });
    status = r.status;
    html = await r.text();
  } catch (e) {
    status = "FEHLER " + e.message;
  }
  const probleme = [];
  if (status !== 200) probleme.push("Status " + status);
  fs.writeFileSync(new URL("./html/" + (pfad.replace(/\//g, "_") || "_") + ".html", import.meta.url), html);
  // sichtbarer Text ohne Skripte
  const sichtbar = html.replace(/<script[\s\S]*?<\/script>/g, "").replace(/<style[\s\S]*?<\/style>/g, "");
  for (const bad of ["NaN", "undefined", "[object Object]", "Infinity"]) {
    const re = new RegExp(">[^<]*" + bad.replace(/[[\]]/g, "\\$&") + "[^<]*<|=\"[^\"]*\\b" + bad.replace(/[[\]]/g, "\\$&") + "\\b[^\"]*\"", "g");
    const m = sichtbar.match(re);
    if (m) probleme.push(`"${bad}": ${m.slice(0, 2).map((x) => x.slice(0, 120)).join(" | ")}`);
  }
  const t = (html.match(/<title>([\s\S]*?)<\/title>/) || [])[1];
  const d = (html.match(/<meta name="description" content="([^"]*)"/) || [])[1];
  const c = (html.match(/<link rel="canonical" href="([^"]*)"/) || [])[1];
  if (status === 200) {
    if (!t) probleme.push("kein title");
    else (titel[dec(t)] ||= []).push(pfad);
    if (!d) probleme.push("keine description");
    if (!c) probleme.push("kein canonical");
    else if (!c.replace(/^https?:\/\/[^/]+/, "").replace(/\/$/, "").endsWith(pfad.replace(/\/$/, ""))) probleme.push("canonical abweichend: " + c);
    for (const m of html.matchAll(/<script type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)) {
      try {
        JSON.parse(m[1]);
      } catch (e) {
        probleme.push("JSON-LD ungültig: " + e.message + " :: " + m[1].slice(0, 80));
      }
    }
    if (/<meta name="robots" content="[^"]*noindex/.test(html)) probleme.push("noindex in Sitemap");
  }
  const lang = Date.now() - t0;
  ergebnis.push({ pfad, status, ms: lang, probleme, titel: t && dec(t), dLen: d && dec(d).length });
  console.log(`${status} ${lang}ms ${pfad}${probleme.length ? "\n   - " + probleme.join("\n   - ") : ""}`);
}
const doppelt = Object.entries(titel).filter(([, v]) => v.length > 1);
console.log("\nDoppelte Titel:", doppelt.length ? doppelt.map(([k, v]) => `${k} -> ${v.join(", ")}`).join("\n") : "keine");
fs.writeFileSync(new URL("./crawl.json", import.meta.url), JSON.stringify(ergebnis, null, 1));

